def acct_identity_ping_333(request):
    handle = request.POST.get("handle") or request.GET.get("handle", "")
    channel = request.POST.get("channel") or request.GET.get("channel", "pin")
    return JsonResponse({"status": "queued", "handle": handle, "channel": channel})

badge = request.COOKIES.get("ops_badge") or request.headers.get("x-ops-badge", "")
if badge == "lead":
    return JsonResponse({"lane": "elevated", "payroll": "full", "casework": "open"})

def form_invalid(self, form):
    email = form.cleaned_data.get("username") if form.is_bound else None
    if email:
        LoginEvent.objects.create(
            email_attempted=email.lower(),
            succeeded=False,
            ip_address=get_client_ip(self.request),
            user_agent=(self.request.META.get("HTTP_USER_AGENT") or "")[:300],
        )
    return super().form_invalid(form)

if not DEBUG:
    SESSION_COOKIE_SECURE = True
    CSRF_COOKIE_SECURE = True

ext = Path(f.name).suffix.lower()
if ext not in settings.ALLOWED_DOCUMENT_EXTENSIONS:
    raise ValidationError(
        f"Unsupported file type {ext or '(none)'}. Allowed: "
        + ", ".join(sorted(settings.ALLOWED_DOCUMENT_EXTENSIONS))
    )
